//! AI Studio presentation adapter for the GameEngine-managed local inference runtime.
//!
//! Runtime installation, WSL ownership, model hashing/copying, process lifecycle,
//! and loopback transport remain in [`crate::managed_local_runtime`]. This module
//! only turns those GUI-free contracts into explicit user setup actions.

use crate::managed_local_runtime::{
    ManagedExecutionEnvironment, ManagedLocalRuntime, ManagedLocalTask, ManagedLocalTaskOutcome,
    ManagedSetupStatus, PINNED_LLAMA_CPP_REVISION, PINNED_LLAMA_CPP_TAG,
};
use crate::native_agent::{
    managed_model_capability_profile, InstalledModelInventory, ManagedModelConfig,
    ModelCapabilityProfile, NativeModelConfig,
};
use eframe::egui;
use std::path::PathBuf;

pub(crate) struct ManagedLocalAiStudio {
    runtime: ManagedLocalRuntime,
    environment: ManagedExecutionEnvironment,
    model_id: String,
    task: Option<ManagedLocalTask>,
    setup_status: ManagedSetupStatus,
    additional_storage_bytes: Option<u64>,
    status: Option<String>,
    confirm_remove_wsl: bool,
    #[cfg(feature = "visual-validation")]
    visual_fixture: bool,
}


include!("managed_local_ai_studio/query.rs");
include!("managed_local_ai_studio/show.rs");
include!("managed_local_ai_studio/helpers_impl.rs");
include!("managed_local_ai_studio/helpers.rs");
